    r=random.randrange(R);end=st[r+1] if r+1<R else st[r]+100;aa.append(random.randrange(st[r],min(end,st[r]+100)))
   allb.append((v,rep,aa));vb[v].append((rep,aa))
 per=[];fixed=0
